//! Deterministic model engine for coordination tests.

use std::collections::VecDeque;

use super::harness::{AgentEngine, Message};

/// A deterministic mock engine that records every transcript it receives.
#[derive(Debug)]
pub(crate) struct ScriptedAgent {
    name: String,
    responses: VecDeque<Result<String, String>>,
    calls: Vec<Vec<Message>>,
}

impl ScriptedAgent {
    pub(crate) fn new(
        name: impl Into<String>,
        responses: impl IntoIterator<Item = Result<&'static str, &'static str>>,
    ) -> Self {
        Self {
            name: name.into(),
            responses: responses
                .into_iter()
                .map(|response| response.map(str::to_owned).map_err(str::to_owned))
                .collect(),
            calls: Vec::new(),
        }
    }

    pub(crate) fn calls(&self) -> &[Vec<Message>] {
        &self.calls
    }
}

impl AgentEngine for ScriptedAgent {
    fn name(&self) -> &str {
        &self.name
    }

    fn respond(&mut self, transcript: &[Message]) -> Result<String, String> {
        self.calls.push(transcript.to_vec());
        self.responses
            .pop_front()
            .unwrap_or_else(|| Err(format!("{} has no scripted response", self.name)))
    }
}

//! A deterministic participant that replays a fixed script.

#![allow(dead_code)]

use tinyhivemind::{Sequence, SessionMessage};
use tinyhivemind_hive::{
    HiveTurn, Phase,
    quorum::{ConsensusState, QuorumPolicy, consensus, standings},
    trace::read,
};

use super::hive_harness::HiveAgent;

/// A participant that speaks from a script, recording what each turn saw.
pub(crate) struct ScriptedAgent {
    id: String,
    lines: std::collections::VecDeque<Result<String, String>>,
    /// One entry per turn taken: the sequences this turn was actually shown.
    calls: Vec<Vec<u64>>,
    /// What it says once its script runs out.
    filler: String,
    /// The room's quorum rule, so an out-of-script commit turn records what
    /// the room actually carried rather than what the crate default would have.
    quorum: QuorumPolicy,
}

impl ScriptedAgent {
    pub(crate) fn new<'a>(id: &str, lines: impl IntoIterator<Item = &'a str>) -> Self {
        Self {
            id: id.to_owned(),
            lines: lines.into_iter().map(|line| Ok(line.to_owned())).collect(),
            calls: Vec::new(),
            filler: "!question Nothing further from me.".to_owned(),
            quorum: QuorumPolicy::DEFAULT,
        }
    }

    /// Tell the participant which quorum rule the room is running.
    pub(crate) fn set_quorum(&mut self, quorum: QuorumPolicy) {
        self.quorum = quorum;
    }

    /// A participant whose first model call fails.
    pub(crate) fn failing(id: &str, message: &str) -> Self {
        let mut agent = Self::new(id, []);
        agent.lines.push_back(Err(message.to_owned()));
        agent
    }

    pub(crate) fn calls(&self) -> &[Vec<u64>] {
        &self.calls
    }
}

impl HiveAgent for ScriptedAgent {
    fn id(&self) -> &str {
        &self.id
    }

    fn speak(&mut self, turn: &HiveTurn, visible: &[SessionMessage]) -> Result<String, String> {
        self.calls
            .push(visible.iter().map(|message| message.sequence.0).collect());
        if let Some(line) = self.lines.pop_front() {
            return line;
        }
        if turn.phase == Phase::Commit {
            return Ok(commit_line(visible, self.quorum));
        }
        Ok(self.filler.clone())
    }
}

/// What an out-of-script participant says once the room has moved to
/// [`Phase::Commit`]: the carried topic, recomputed from what this turn can
/// see, rather than a `!question` that would never record a decision.
fn commit_line(visible: &[SessionMessage], policy: QuorumPolicy) -> String {
    let messages: Vec<SessionMessage> = visible.iter().map(|message| (*message).clone()).collect();
    let traces = read(&messages);
    let at = messages
        .last()
        .map_or(Sequence(0), |message| message.sequence);
    if let Ok(standing) = standings(&traces, at, &policy)
        && let ConsensusState::Quorum { topic } = consensus(&standing, &policy)
    {
        return format!("!commit #{topic} Recording the decision.");
    }
    "!question Nothing further from me.".to_owned()
}

//! Integration tests for the public crate surface.
//!
//! These tests link against the crate as a downstream consumer would: they can
//! only use what `src/lib.rs` exposes. Treat them as the regression suite for
//! the crate's public contract — if a change breaks a test here, it is a
//! breaking change for users.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use tinyhivemind_core::chat::{GENERAL_DESK, MAIN_THREAD_ID, is_general_chat, same_conversation};
use tinyhivemind_core::{
    desk::{Desk, DeskMember, DeskOrder, DeskSet, ResponderMode},
    dispatch::{
        DispatchConversation, DispatchKey, MentionDispatchDecision, MentionDispatchInput,
        MentionDispatchPolicy, mention_dispatch,
    },
    error::Error,
    mention::{MentionAuthor, MentionTarget, direct_responder, mentioned_members, resolve},
    roster::{Person, Roster, RosterMember},
};

#[test]
fn conversation_identity_is_available_to_consumers() {
    assert!(is_general_chat(Some(MAIN_THREAD_ID)));
    assert!(is_general_chat(Some(GENERAL_DESK)));
    assert!(!is_general_chat(Some("engineering")));
}

#[test]
fn conversation_folding_is_available_to_consumers() {
    assert!(same_conversation(None, Some(GENERAL_DESK)));
    assert!(!same_conversation(Some("engineering"), Some(GENERAL_DESK)));
}

/// The constants are public because a host has to journal under them and pin
/// its own glossary against them.
#[test]
fn the_general_spellings_are_named_constants() {
    assert_eq!(MAIN_THREAD_ID, "main");
    assert_eq!(GENERAL_DESK, "General");
}

#[test]
fn desk_overlays_are_available_to_consumers_under_the_desk_module() {
    let declared = [Desk {
        id: "engineering".into(),
        name: "Engineering".into(),
        description: None,
        members: vec!["alice".into(), "bob".into()],
        responder_mode: ResponderMode::Lead,
    }];
    let additions = [DeskMember {
        desk_id: "engineering".into(),
        agent_id: "cara".into(),
    }];
    let orders = [DeskOrder {
        desk_id: "engineering".into(),
        ordered: vec!["cara".into(), "alice".into(), "bob".into()],
    }];
    let desks = DeskSet::new(&declared, &[], &additions, &orders, &[]);

    assert_eq!(desks.resolve_id("Engineering").unwrap(), "engineering");
    assert_eq!(
        desks.members("engineering").unwrap(),
        ["cara", "alice", "bob"]
    );
    assert_eq!(desks.lead("Engineering").unwrap(), Some("cara"));
}

#[test]
fn desk_failures_are_available_as_the_crate_error_type() {
    let desks = DeskSet::new(&[], &[], &[], &[], &[]);
    assert_eq!(
        desks.resolve_id("unknown").unwrap_err(),
        Error::UnknownDesk {
            identity: "unknown".into()
        }
    );
}

#[test]
fn roster_and_mention_decisions_are_available_to_consumers() {
    let members = [
        RosterMember {
            id: "alice".into(),
            name: Some("Alice".into()),
        },
        RosterMember {
            id: "bob".into(),
            name: Some("Bob".into()),
        },
    ];
    let people = [Person {
        id: "person-1".into(),
        label: "Operator".into(),
    }];
    let declared = [Desk {
        id: "engineering".into(),
        name: "Engineering".into(),
        description: None,
        members: vec!["alice".into(), "bob".into()],
        responder_mode: ResponderMode::Lead,
    }];
    let roster = Roster::new(&members, &people, &[]);
    let desks = DeskSet::new(&declared, &[], &[], &[], &[]);

    let mentions = resolve(
        "@Alice please coordinate with @#Engineering",
        None,
        &MentionAuthor::Person {
            id: "person-1".into(),
        },
        &roster,
        &desks,
    );

    assert_eq!(direct_responder(&mentions, &roster), Some("alice"));
    assert_eq!(
        mentioned_members(
            &mentions,
            Some("engineering"),
            Some("alice"),
            &roster,
            &desks
        ),
        ["bob"]
    );
    assert_eq!(
        mentions[0].target,
        MentionTarget::Agent { id: "alice".into() }
    );
}

#[test]
fn bounded_dispatch_decision_is_available_to_consumers() {
    let members = [
        RosterMember {
            id: "alice".into(),
            name: None,
        },
        RosterMember {
            id: "bob".into(),
            name: None,
        },
    ];
    let roster = Roster::new(&members, &[], &[]);
    let input = MentionDispatchInput {
        key: DispatchKey {
            trigger_sequence: 8,
        },
        conversation: DispatchConversation {
            desk_id: "engineering".into(),
            thread_root: None,
        },
        author_id: "alice".into(),
        content: "@bob".into(),
        mentions: vec![tinyhivemind_core::mention::Mention {
            target: MentionTarget::Agent { id: "bob".into() },
            text: "@bob".into(),
            offset: 0,
            quiet: false,
        }],
        hop: 0,
    };
    let decision = mention_dispatch(
        MentionDispatchPolicy {
            enabled: true,
            max_hops: 2,
        },
        &input,
        &roster,
    )
    .unwrap();
    assert!(
        matches!(decision, MentionDispatchDecision::One { request } if request.target_id == "bob")
    );
}

#[test]
fn selection_ranking_is_available_to_consumers() {
    use tinyhivemind_core::select::{
        Candidate, MatchField, MatchKind, Pattern, SELECT_LIMIT, rank, rank_pattern, regex_source,
        score, score_pattern,
    };

    let candidates = [
        Candidate::new("alice", "Alice Nakamura"),
        Candidate::new("bob", "Bob Ferrante").with_detail("reviews Alice's changes"),
    ];
    let hits = rank("alice", &candidates, SELECT_LIMIT);
    // The id is the query exactly; the label only starts with it, so the id is
    // the field reported.
    assert_eq!(hits[0].id, "alice");
    assert_eq!(hits[0].field, MatchField::Id);
    assert_eq!(hits[0].kind, MatchKind::Exact);
    assert_eq!(hits[1].id, "bob");
    assert_eq!(hits[1].field, MatchField::Detail);
    assert_eq!(
        rank("nakamura", &candidates, SELECT_LIMIT)[0].field,
        MatchField::Label
    );

    assert_eq!(
        rank_pattern(&Pattern::Text("alice"), &candidates, SELECT_LIMIT).len(),
        hits.len()
    );
    assert_eq!(
        score("alice", "Alice"),
        score_pattern(&Pattern::Text("alice"), "Alice")
    );
    assert_eq!(regex_source("/^ali/"), Some("^ali"));
    assert_eq!(SELECT_LIMIT, 8);
}

#[test]
fn name_searches_are_available_to_consumers() {
    use tinyhivemind_core::{find, select::SELECT_LIMIT};

    let members = [
        RosterMember {
            id: "alice".into(),
            name: Some("Alice Nakamura".into()),
        },
        RosterMember {
            id: "bob".into(),
            name: Some("Bob Ferrante".into()),
        },
    ];
    let people = [Person {
        id: "u-1".into(),
        label: "Dana Okoro".into(),
    }];
    let roster = Roster::new(&members, &people, &[]);
    let declared = [Desk {
        id: "engineering".into(),
        name: "Engineering".into(),
        description: Some("Ship the product".into()),
        members: vec!["alice".into()],
        responder_mode: ResponderMode::Lead,
    }];
    let desks = DeskSet::new(&declared, &[], &[], &[], &[]);

    assert_eq!(find::agents("naka", &roster, SELECT_LIMIT)[0].id, "alice");
    assert_eq!(find::people("okoro", &roster, SELECT_LIMIT)[0].id, "u-1");
    assert_eq!(
        find::desks("product", &desks, SELECT_LIMIT)[0].id,
        "engineering"
    );
}

/// Two agents, one on each of two desks.
fn two_desks() -> ([RosterMember; 2], [Desk; 2]) {
    (
        [
            RosterMember {
                id: "ada".into(),
                name: Some("Ada".into()),
            },
            RosterMember {
                id: "linus".into(),
                name: Some("Linus".into()),
            },
        ],
        [
            Desk {
                id: "payments".into(),
                name: "Payments".into(),
                description: None,
                members: vec!["ada".into()],
                responder_mode: ResponderMode::Lead,
            },
            Desk {
                id: "platform".into(),
                name: "Platform".into(),
                description: None,
                members: vec!["linus".into()],
                responder_mode: ResponderMode::Lead,
            },
        ],
    )
}

#[test]
fn a_referral_crosses_a_desk_and_finds_its_way_home() {
    use tinyhivemind_core::referral::{
        ReferralDecision, ReferralInput, ReferralKind, ReferralOrigin, ReferralPolicy,
        ReferralReach, referral,
    };

    let (members, records) = two_desks();
    let roster = Roster::new(&members, &[], &[]);
    let desks = DeskSet::new(&records, &[], &[], &[], &[]);
    let policy = ReferralPolicy {
        enabled: true,
        max_hops: 2,
        reach: ReferralReach::Desks,
        returns: true,
    };

    // Ada asks the platform desk, from inside a thread on her own desk.
    let asking = ReferralInput {
        key: DispatchKey {
            trigger_sequence: 12,
        },
        conversation: DispatchConversation {
            desk_id: "payments".into(),
            thread_root: Some(9),
        },
        author_id: "ada".into(),
        content: "@#platform does the gateway retry on 503?".into(),
        mentions: resolve(
            "@#platform does the gateway retry on 503?",
            None,
            &MentionAuthor::Agent { id: "ada".into() },
            &roster,
            &desks,
        ),
        hop: 0,
        origin: None,
    };
    let ReferralDecision::One { referral: out } =
        referral(policy, &asking, &roster, &desks).expect("well formed")
    else {
        panic!("the desk mention should have crossed");
    };
    assert_eq!(out.kind, ReferralKind::Forward);
    assert_eq!(out.target_id, "linus");
    assert_eq!(out.to.desk_id, "platform");
    // A crossing referral lands on the desk channel, never in a thread.
    assert_eq!(out.to.thread_root, None);
    assert_eq!(out.child_hop, 1);

    // Linus answers on his own desk, and the answer finds the thread that asked.
    let answering = ReferralInput {
        key: DispatchKey {
            trigger_sequence: 4,
        },
        conversation: DispatchConversation {
            desk_id: "platform".into(),
            thread_root: None,
        },
        author_id: "linus".into(),
        content: "It retries twice with jitter.".into(),
        mentions: Vec::new(),
        hop: out.child_hop,
        origin: out.origin.clone(),
    };
    let ReferralDecision::One { referral: home } =
        referral(policy, &answering, &roster, &desks).expect("well formed")
    else {
        panic!("the answer should have come home");
    };
    assert_eq!(home.kind, ReferralKind::Return);
    assert_eq!(home.target_id, "ada");
    assert_eq!(
        home.to,
        DispatchConversation {
            desk_id: "payments".into(),
            thread_root: Some(9),
        },
    );
    assert_eq!(home.child_hop, 2);
    assert_eq!(home.origin, None);
    assert_eq!(
        out.origin,
        Some(ReferralOrigin {
            conversation: DispatchConversation {
                desk_id: "payments".into(),
                thread_root: Some(9),
            },
            asker_id: "ada".into(),
        }),
    );

    // And the round trip is over: Ada's relay may not start another.
    let relaying = ReferralInput {
        hop: home.child_hop,
        origin: None,
        conversation: home.to.clone(),
        author_id: "ada".into(),
        ..asking
    };
    assert!(matches!(
        referral(policy, &relaying, &roster, &desks).expect("well formed"),
        ReferralDecision::None { .. },
    ));
}

//! Public API regression tests for the runtime crate.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use tinyhivemind::aside::Audience;
use tinyhivemind::aside::Viewer;
use tinyhivemind::{
    Conversation, EnqueueOutcome, EnqueueRefusal, MentionDispatchOutcome, PAGE_SIZE,
    PRESENT_SET_LIMIT, SCAN_LIMIT, SESSION_WINDOW, Sequence, SessionAuthor, SessionMessage,
    initialized_state, note_present,
    responder::{ResponderRung, SelectionDisposition},
};

#[test]
fn root_exports_runtime_records_and_constants() {
    let conversation = Conversation {
        desk_id: "engineering".into(),
        desk_name: "Engineering".into(),
        thread_root: Some(Sequence(3)),
    };
    let message = SessionMessage {
        sequence: Sequence(4),
        author: SessionAuthor::Operator,
        content: "hello".into(),
        audience: Audience::Aside {
            members: vec!["linus".into()],
        },
        elided: Some(tinyhivemind::Elision {
            through: Sequence(4),
            messages: 1,
            settled_at: None,
        }),
    };
    assert_eq!(conversation.thread_root, Some(Sequence(3)));
    assert_eq!(message.sequence, Sequence(4));
    assert_eq!(
        message.audience,
        Audience::Aside {
            members: vec!["linus".into()]
        }
    );
    assert_eq!(
        message.elided.as_ref().map(|elision| elision.messages),
        Some(1)
    );
    assert_eq!((SESSION_WINDOW, PAGE_SIZE, SCAN_LIMIT), (30, 512, 2048));
}

#[test]
fn root_exports_continuous_sharing_state() {
    let mut state = initialized_state(
        Conversation {
            desk_id: "engineering".into(),
            desk_name: "Engineering".into(),
            thread_root: None,
        },
        Sequence(10),
    );
    assert!(note_present(&mut state, Sequence(11)).is_ok());
    assert!(state.present_above_watermark.contains(&Sequence(11)));
    assert_eq!(PRESENT_SET_LIMIT, 64);
}

#[test]
fn root_reexports_the_core_algebra() {
    assert!(tinyhivemind::chat::same_conversation(None, Some("General")));
    assert_eq!(ResponderRung::DeskDefault, ResponderRung::DeskDefault);
    assert_eq!(
        SelectionDisposition::Unavailable,
        SelectionDisposition::Unavailable
    );
}

#[test]
fn root_exports_dispatch_outcomes_and_conversation_mapping() {
    let conversation = Conversation {
        desk_id: "engineering".into(),
        desk_name: "Engineering".into(),
        thread_root: Some(Sequence(12)),
    };
    let scope = tinyhivemind::dispatch::DispatchConversation::from(&conversation);
    assert_eq!(scope.desk_id, "engineering");
    assert_eq!(scope.thread_root, Some(12));
    assert_eq!(
        MentionDispatchOutcome::Enqueued,
        MentionDispatchOutcome::Enqueued
    );
    assert_eq!(EnqueueOutcome::Already, EnqueueOutcome::Already);
    assert_eq!(EnqueueRefusal::Unauthorized, EnqueueRefusal::Unauthorized);

    let general = tinyhivemind::dispatch::DispatchConversation::from(&Conversation {
        desk_id: "MAIN".into(),
        desk_name: "General".into(),
        thread_root: Some(Sequence(12)),
    });
    assert_eq!(general.desk_id, tinyhivemind::chat::GENERAL_DESK);
    assert_eq!(general.thread_root, Some(12));
}

#[test]
fn root_exports_search_records_and_constants() {
    use tinyhivemind::{
        EXCERPT_CHARS, MessageHit, SEARCH_LIMIT, SEARCH_SCAN, SearchPattern, SearchQuery,
    };

    let query = SearchQuery::new("/^ship/", Viewer::Operator)
        .in_conversation(Conversation {
            desk_id: "engineering".into(),
            desk_name: "Engineering".into(),
            thread_root: None,
        })
        .by_author("alice");
    assert_eq!(
        query.pattern,
        SearchPattern::Regex {
            source: "^ship".into()
        }
    );
    assert_eq!(query.viewer, Viewer::Operator);
    assert_eq!(query.limit, SEARCH_LIMIT);
    assert_eq!((SEARCH_LIMIT, SEARCH_SCAN, EXCERPT_CHARS), (10, 2048, 96));

    let hit = MessageHit {
        sequence: Sequence(4),
        chat_id: None,
        parent: None,
        author: SessionAuthor::Operator,
        excerpt: "ship it".into(),
        score: 1100,
        kind: tinyhivemind::select::MatchKind::Exact,
    };
    assert_eq!(hit.sequence, Sequence(4));
}

#[tokio::test]
async fn the_search_viewer_argument_narrows_what_is_matched() {
    use std::{pin::Pin, sync::Mutex};
    use tinyhivemind::{LogMessage, SearchQuery, search_messages};

    struct FixedLog(Mutex<Vec<LogMessage>>);

    impl tinyhivemind::SessionLog for FixedLog {
        fn read_before(
            &self,
            _before: Option<Sequence>,
            _limit: usize,
        ) -> tinyhivemind::SessionFuture<'_> {
            let messages = std::mem::take(&mut *self.0.lock().expect("log lock is not poisoned"));
            Box::pin(async move {
                Ok(tinyhivemind::SessionPage {
                    messages,
                    next_before: None,
                })
            }) as Pin<Box<_>>
        }
    }

    let row = LogMessage {
        sequence: Sequence(1),
        chat_id: None,
        parent: None,
        author: SessionAuthor::Agent {
            id: "ada".into(),
            label: "Ada".into(),
        },
        content: "we should ship the migration tonight".into(),
        audience: Audience::Aside {
            members: vec!["linus".into()],
        },
    };
    let log = FixedLog(Mutex::new(vec![row.clone()]));

    let outsider_hits = search_messages(&log, &SearchQuery::new("ship", Viewer::Operator))
        .await
        .expect("outsider search succeeds");
    // The row was already consumed by the outsider search above, so reseed it
    // for the member search — the point under test is what each viewer's own
    // call returns, not a shared cursor.
    *log.0.lock().expect("log lock is not poisoned") = vec![row];
    let member_hits = search_messages(
        &log,
        &SearchQuery::new("ship", Viewer::Agent { id: "linus".into() }),
    )
    .await
    .expect("member search succeeds");

    assert!(
        !outsider_hits.is_empty(),
        "the operator viewer reads every audience"
    );
    assert!(
        !member_hits.is_empty(),
        "an addressed member reads its own aside"
    );

    *log.0.lock().expect("log lock is not poisoned") = vec![LogMessage {
        sequence: Sequence(1),
        chat_id: None,
        parent: None,
        author: SessionAuthor::Agent {
            id: "ada".into(),
            label: "Ada".into(),
        },
        content: "we should ship the migration tonight".into(),
        audience: Audience::Aside {
            members: vec!["linus".into()],
        },
    }];
    let excluded_hits = search_messages(
        &log,
        &SearchQuery::new("ship", Viewer::Agent { id: "grace".into() }),
    )
    .await
    .expect("outsider agent search succeeds");
    assert!(
        excluded_hits.is_empty(),
        "an agent outside the aside's audience must not match its content"
    );
}

#[test]
fn root_exports_the_pin_fold_and_its_briefing_note() {
    use tinyhivemind::{LogMessage, PIN_LIMIT, PinAction, fold_pins, pin_note, read_directives};

    let rows = [
        LogMessage {
            sequence: Sequence(1),
            chat_id: None,
            parent: None,
            author: SessionAuthor::Operator,
            content: "the rate limiter resets at midnight UTC".into(),
            audience: Audience::Desk,
        },
        LogMessage {
            sequence: Sequence(2),
            chat_id: None,
            parent: None,
            author: SessionAuthor::Agent {
                id: "ada".into(),
                label: "Ada".into(),
            },
            content: "!pin ^1 #limits keep this".into(),
            audience: Audience::Aside {
                members: vec!["linus".into()],
            },
        },
    ];
    let board = fold_pins(&rows, &Viewer::Operator, PIN_LIMIT);
    assert_eq!(board[0].sequence, Sequence(1));
    assert_eq!(board[0].label.as_deref(), Some("limits"));
    assert_eq!(
        pin_note(&board).expect("a note").heading,
        "Pinned in this conversation"
    );
    assert_eq!(
        read_directives("!unpin ^1", &SessionAuthor::Operator, Sequence(3))[0].action,
        PinAction::Unpin
    );

    // The `!pin` marker is inside an aside addressed to `linus`, not to the
